theme.css:
/* ==== INTERFACE ====
   token  --bg #f8fafc          页面整体背景色｜画布底色
   token  --panel #ffffff       卡片与操作台面板底色｜.panel 填色
   token  --text #0f172a        主正文与主要标题文字｜最高对比深冷色
   token  --muted #64748b       次要说明、图表轴线与中性分界线｜成句次级文本与边框
   token  --focus #2563eb       键盘焦点与选中操作项高亮外框｜交互轮廓线
   token  --cls-pos #1d4ed8     正类样本(+1)与正向分类器区域｜点、填充与标签
   token  --cls-neg #b91c1c     负类样本(-1)与负向分类器区域｜点、填充与标签
   token  --boundary #0f766e    决策分界线(决策桩划分面)与判决面｜分界线与阈值标记
   token  --weight #d97706      样本权重更新与重权放大警示｜加权采样圈与更新增量
   token  --fs-h1 34px          一级标题文字字号
   token  --fs-h2 22px          区块与二级标题字号
   token  --fs-lead 19px        引导句与重点导引文字
   token  --fs-body 18px        正文文字标准字号
   token  --fs-sec 16px         次级成句说明与面板内容字号
   token  --fs-label 15px       表单控件标签与图例文字
   token  --fs-tick 13px        纯数字刻度与等宽读数
   版心   1488×844              #stage 包含 pad-y:28px pad-x:56px
   版式   .focus                标题后单一主工作区（自适应撑满）
   版式   .split-2              左右对等两栏对照工作区
   版式   .col-main-side        左侧主演示区 + 右侧度量控制边栏
   组件   .panel                仪器面板、读数板与代码外框
   组件   .panel.q              无底色边框面板（问题或独立作答区）
   组件   .big                  关键指标数值展示
   组件   .big.sm               小型关键数值展示
   组件   .big.lg               大型关键数值展示
   组件   .num                  纯数字与等宽指标数据
   组件   .unit                 指标单位符号
   组件   .btn                  交互动作触发按钮
   组件   .btns                 按钮工具栏组合
   组件   .ctl                  带标签的操作控件行
   组件   .hint                 操作指导与提示条
   组件   .tag                  状态与算法轮次标签
   组件   .legend               分类图例容器
   组件   .quiz                 检测题包裹器
   组件   .opt                  选项按键
   组件   .fb                   作答反馈区
   组件   .cvbox                Canvas/SVG 图形容器视口
   组件   .lead                 导言段落
   组件   .small                注记文字
   组件   .note                 算法提示与关键性质批注
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;

  --bg: #f8fafc;
  --panel: #ffffff;
  --text: #0f172a;
  --muted: #64748b;
  --focus: #2563eb;

  --cls-pos: #1d4ed8;
  --cls-neg: #b91c1c;
  --boundary: #0f766e;
  --weight: #d97706;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --font-sans: "PingFang SC", "Microsoft YaHei", "Noto Sans SC", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: "Fira Code", "SFMono-Regular", Consolas, Menlo, "Liberation Mono", monospace;

  font-family: var(--font-sans);
  color: var(--text);
  background-color: var(--bg);
  font-feature-settings: "cv02", "cv03", "cv04", "cv11", "tnum";
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  box-sizing: border-box;
  width: 1600px;
  height: 900px;
  overflow: hidden;
  background-color: var(--bg);
}

/* 基础版式 */
.focus {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  gap: 20px;
}

.split-2 {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  min-height: 0;
}

.col-main-side {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 24px;
  min-height: 0;
}

/* 结构容器 */
.panel {
  background-color: var(--panel);
  border: 1px solid var(--muted);
  border-radius: 6px;
  padding: 20px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.panel.q {
  background-color: transparent;
  border: 1px dashed var(--muted);
}

.cvbox {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 0;
  border-radius: 4px;
  overflow: hidden;
  background-color: #ffffff;
}

/* 标题与文字阶层 */
h1 {
  font-size: var(--fs-h1);
  font-weight: 700;
  line-height: 1.25;
  margin: 0 0 12px 0;
  color: var(--text);
}

h2 {
  font-size: var(--fs-h2);
  font-weight: 600;
  line-height: 1.3;
  margin: 0 0 12px 0;
  color: var(--text);
}

.lead {
  font-size: var(--fs-lead);
  line-height: 1.45;
  color: var(--text);
  margin: 0 0 16px 0;
}

p, .body-text {
  font-size: var(--fs-body);
  line-height: 1.5;
  margin: 0 0 12px 0;
  color: var(--text);
}

.small {
  font-size: var(--fs-sec);
  line-height: 1.45;
  color: var(--muted);
}

.note {
  font-size: var(--fs-sec);
  line-height: 1.45;
  padding: 10px 14px;
  border-left: 3px solid var(--boundary);
  background-color: #f1f5f9;
  border-radius: 0 4px 4px 0;
  color: var(--text);
}

/* 数值展示 */
.big {
  font-size: 40px;
  line-height: 1.1;
  font-weight: 700;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.big.sm {
  font-size: 28px;
}

.big.lg {
  font-size: 56px;
}

.num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.unit {
  font-size: var(--fs-sec);
  font-weight: 400;
  color: var(--muted);
  margin-left: 4px;
}

/* 控件与按钮 */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  padding: 0 18px;
  font-size: var(--fs-label);
  font-weight: 500;
  border-radius: 4px;
  border: 1px solid var(--muted);
  background: var(--panel);
  color: var(--text);
  cursor: pointer;
  user-select: none;
  text-decoration: none;
}

.btn:hover {
  background: #f1f5f9;
}

.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  background: #e2e8f0;
}

.btn.primary {
  background: var(--text);
  color: #ffffff;
  border-color: var(--text);
}

.btn.primary:hover {
  background: #1e293b;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btns {
  display: inline-flex;
  gap: 10px;
  align-items: center;
}

.ctl {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: var(--fs-label);
  color: var(--text);
}

.ctl label {
  font-weight: 500;
  min-width: 80px;
}

input[type="range"] {
  accent-color: var(--text);
  height: 6px;
  cursor: pointer;
}

.hint {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: var(--fs-label);
  color: var(--muted);
}

/* 图例与标记 */
.tag {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 3px;
  font-size: var(--fs-label);
  font-weight: 600;
  font-family: var(--font-mono);
  background: #e2e8f0;
  color: var(--text);
}

.tag.pos {
  background: #dbeafe;
  color: var(--cls-pos);
}

.tag.neg {
  background: #fee2e2;
  color: var(--cls-neg);
}

.tag.weight {
  background: #fef3c7;
  color: var(--weight);
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  font-size: var(--fs-label);
  color: var(--text);
}

.legend > .li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend .sw {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: inline-block;
}

.legend .sw.line {
  width: 20px;
  height: 3px;
  border-radius: 1px;
}

/* 测验与问答 */
.quiz {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.opt {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 12px 16px;
  border-radius: 4px;
  border: 1px solid var(--muted);
  background: var(--panel);
  font-size: var(--fs-body);
  text-align: left;
  cursor: pointer;
  color: var(--text);
}

.opt:hover {
  background: #f8fafc;
}

.opt.selected {
  border-color: var(--focus);
  background: #eff6ff;
  font-weight: 500;
}

.opt.correct {
  border-color: var(--boundary);
  background: #f0fdf4;
}

.opt.wrong {
  border-color: var(--cls-neg);
  background: #fef2f2;
}

.fb {
  padding: 12px 16px;
  border-radius: 4px;
  font-size: var(--fs-sec);
  line-height: 1.45;
  background: #f1f5f9;
  border: 1px solid var(--muted);
}

/* 代码显示 */
pre, code {
  font-family: var(--font-mono);
}

pre {
  margin: 0;
  padding: 16px;
  background: #0f172a;
  color: #f8fafc;
  border-radius: 4px;
  overflow-x: auto;
  font-size: 15px;
  line-height: 1.5;
}

/* SVG 尺寸保护 */
svg .bar, svg .cell, svg .box {
  width: auto;
  height: auto;
}
